from pathlib import Path
import json, hashlib
R=Path(__file__).parent
data=json.loads((R/'data.json').read_text())
css=(R/'ui.css').read_text();js=(R/'engine.js').read_text()+'\n'+(R/'ui.js').read_text();maphtml=(R/'map-fragment.html').read_text()
html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#101113"><meta name="description" content="2026년 11월28–30일 여수·순천 여행 장소와 순천 연박 일정 편집"><title>여수-순천 여행</title><style>__CSS__</style></head><body class="map-workspace">
<header class="header" id="appHeader"><button class="brand" id="brand" aria-label="부산·여수·순천 전체 이동 지도"><span>↗</span><div><b>여수-순천 여행</b></div></button><nav class="view-switch" id="viewSwitch" aria-label="보기 선택"><button id="pane-split" data-pane="split" aria-controls="main" aria-pressed="true">전체</button><button id="pane-map" data-pane="map" aria-controls="viewport" aria-pressed="false">지도</button><button id="pane-places" data-pane="places" aria-controls="candidatePanel" aria-pressed="false">장소</button><button id="pane-schedule" data-pane="schedule" aria-controls="planner" aria-pressed="false">일정</button></nav><div class="dates">11.28 — 11.30</div><div class="header-right"><button data-action="info" aria-label="사용 안내">?</button></div></header>
<div class="app"><aside class="sidebar" id="sidebar" aria-label="여행 지역 목록"><button class="sidebar-close" id="closeRegions" aria-label="지역 목록 닫기">×</button><div class="sidebar-head"><h2>지역<small id="regionCount">1</small></h2><select id="regionFilter" aria-label="지역 필터"><option value="all">모든 지역</option><option value="aquarium">아쿠아리움이 있는 지역</option><option value="car">자차 가능한 지역</option><option value="no-car">기차·버스로 가는 지역</option><option value="themepark">테마파크 포함 여행</option></select></div><div class="regions" id="regions"></div></aside>
<main class="main national" id="main"><div class="top-toolbar"><button class="open-regions" id="openRegions" aria-controls="sidebar" aria-expanded="false">☷ 지역</button><div class="map-title"><strong id="mapTitle">여수 · 순천</strong><small id="mapSubtitle"></small></div></div><div class="map-and-candidates"><section class="map-frame"><section class="course-bar" id="courseBar" aria-label="추천 코스 선택" hidden></section><div class="top-buttons"><button id="homeBtn" hidden>부산 포함</button><button id="fitBtn" hidden>두 도시</button></div>__MAP__<div class="map-play-controls" id="mapPlayback" hidden><button id="mapPlay" data-action="play">▶ 일정 시작</button><button id="arrivalReplay" data-action="arrival">부산부터 보기</button><button id="skipArrival" data-action="skip-arrival" hidden>도착지 보기</button></div><div class="map-help" id="mapHelp"></div><div class="play-caption" id="playCaption" hidden></div></section><section class="candidate-panel" id="candidatePanel" aria-label="장소 후보 목록"></section></div><section class="planner" id="planner" aria-label="24시간 여행 일정 편집" hidden></section></main></div>
<button class="backdrop" id="regionsBackdrop" aria-label="지역 목록 닫기" hidden></button><dialog class="dialog" id="detail" aria-labelledby="detailTitle"><header class="dialog-head"><h2 id="detailTitle"></h2><button id="closeDetail" aria-label="장소 정보 닫기">×</button></header><div class="dialog-body" id="detailBody"></div></dialog><dialog class="dialog" id="dialog" aria-labelledby="dialogTitle"><header class="dialog-head"><h2 id="dialogTitle"></h2><button id="closeDialog" aria-label="설정 창 닫기">×</button></header><div class="dialog-body" id="dialogBody"></div></dialog><div class="toast" id="toast" role="status" hidden></div>
<script type="application/json" id="travelData">__DATA__</script><script type="application/json" id="embeddedPlans">{}</script><script>__JS__</script></body></html>'''
build_id=hashlib.sha256((css+js+maphtml+json.dumps(data,ensure_ascii=False)).encode()).hexdigest()[:16]
html=html.replace('<title>', '<meta name="app-build" content="'+build_id+'"><title>')
html=html.replace('__CSS__',css).replace('__MAP__',maphtml).replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')).replace('__JS__',js)
(R/'yeosu-suncheon.html').write_text(html);(R/'dist').mkdir(exist_ok=True);(R/'dist/index.html').write_text(html)
(R/'dist/.nojekyll').touch()
print('Built',len(html.encode()),'bytes;',len(data),'regions;',sum(len(d['points']) for d in data),'points;',sum(len(d['courses']) for d in data),'courses')

